  const v = viravelDo(l);
  const ea = emAberto(l);
  return h('div', { class: `aberto${v === 'flavio' ? ' viravel' : ''}` },
    h('p', {}, `${lado}.${resto}${ea !== null ? ` Com outros nomes, ${f0(ea)} votos ficaram em aberto.` : ''}`),
