/* Politize sua vizinhança. Folha escrita à mão. Mobile-first: a base é a tela de 360 px. */
*,*::before,*::after{box-sizing:border-box}
:root{
  --paper:#f7f5ee;--paper2:#efece2;--card:#ffffff;--ink:#151812;--ink2:#2a2f27;--muted:#535b54;--line:#d5d2c6;
  --verde:#0b7a3b;--verde-esc:#095f2e;--verde-claro:#0f9d58;--verde-txt:#0a6e35;
  --amarelo:#f2c230;--amarelo2:#ffcc29;--ouro-txt:#7d5b00;
  --azul:#0d2238;--azul2:#1f5f9e;--azul-txt:#1a5189;--azul3:#123150;
  --flavio:#1f5f9e;--lula:#c8412f;--lula-txt:#a8321f;--terceira:#0b7a3b;
  --display:Fraunces,Georgia,serif;--sans:"IBM Plex Sans Condensed",Arial,sans-serif;--mono:"IBM Plex Mono",ui-monospace,monospace;
  --wrap:min(1160px,calc(100% - 32px));--raio:14px;
}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:18px;line-height:1.6;-webkit-font-smoothing:antialiased;overflow-x:hidden}
.wrap{width:var(--wrap);margin:0 auto}
a{color:var(--azul-txt)}
a:hover{color:var(--azul)}
:focus-visible{outline:3px solid var(--amarelo2);outline-offset:2px;border-radius:4px}
.skip{position:absolute;left:-9999px}
