.rot{display:block;font-family:var(--mono);font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin:0 0 6px}
input[type="text"],select{width:100%;min-height:52px;border:2px solid #b9b5a6;border-radius:10px;background:#fff;color:var(--ink);font-family:var(--sans);font-size:1.15rem;padding:10px 14px}
