  if (!uf || !Number.isFinite(zona)) return null;
  const [regras, arq] = await Promise.all([buscar(`${base}fiscal/regras.json`), buscar(`${base}fiscal/${uf}/${zona}.json`)]);
  if (!regras || !arq) return null;
