    if (so($('#f-zona').value) || so($('#q-cep').value) || $('#f-mun').value || $('#f-texto').value) await aplicarBusca();
    trocarModo(modo);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', iniciar);
  else iniciar();
})();

