from pathlib import Path
p=Path('docs/assets/politize/app.js'); s=p.read_text()
old="""  const ufDados = await buscarJSON(`${BASE}uf/${local._uf}.json`).catch(() => null);"""
new="""  // O bloco de fiscalização carrega em paralelo e entra junto com o boletim, sem pular o layout.
  const fiscalP = Promise.race([
    blocoFiscal({ h, buscar: buscarJSON, base: BASE, local, secao: r.secao || null }),
    new Promise((ok) => setTimeout(() => ok(undefined), 6000)),
  ]).catch((e) => {
    console.warn('fiscal', e);
    return undefined;
  });
  const ufDados = await buscarJSON(`${BASE}uf/${local._uf}.json`).catch(() => null);"""
assert old in s; s=s.replace(old,new,1)
old="""  const fisBox = h('div', { class: 'fiscal-slot', 'aria-live': 'polite' });"""
new="""  const fisEl = await fiscalP;
  if (E.atual !== r) return;
  const fisBox = fisEl === null ? null : h('div', { class: 'fiscal-slot' }, fisEl || blocoFiscalReserva());"""
assert old in s; s=s.replace(old,new,1)
old="""  blocoFiscal({ h, buscar: buscarJSON, base: BASE, local, secao: r.secao || null })
    .then((el) => {
      if (E.atual !== r) return;
      if (el) fisBox.replaceChildren(el);
      else fisBox.remove();
    })
    .catch((e) => {
      console.warn('fiscal', e);
      if (E.atual === r) fisBox.replaceChildren(blocoFiscalReserva());
    });
}"""
new="""}"""
assert old in s; s=s.replace(old,new,1)
p.write_text(s)
EOF
grep -n "fisBox\|fiscalP\|fisEl" docs/assets/politize/app.js

